import calendar
from datetime import date


def nth_weekday(year, month, weekday, n) -> str:
    if not isinstance(weekday, int) or not 0 <= weekday <= 6:
        raise ValueError("weekday must be an integer from 0 to 6")

    if not isinstance(n, int) or (n != -1 and not 1 <= n <= 5):
        raise ValueError("n must be 1 through 5 or -1")

    first_day = date(year, month, 1)
    days_in_month = calendar.monthrange(year, month)[1]

    if n == -1:
        day = days_in_month
        last_day = date(year, month, day)
        day -= (last_day.weekday() - weekday) % 7
    else:
        day = 1 + (weekday - first_day.weekday()) % 7 + 7 * (n - 1)
        if day > days_in_month:
            raise ValueError("the requested occurrence does not exist")

    return date(year, month, day).isoformat()
